def get_icon_svg(name):
    """按图标名取 SVG；未注册返回 None（渲染器据此隐藏或留空）。"""
    return ICON_REGISTRY.get((name or '').strip())


def icon_names():
    """全部图标名（供编辑器图标选择器列出）。"""
    return sorted(ICON_REGISTRY.keys())
